// 构造满足要求的最短且字典序最小的序列
vector<int> buildSequence(int n, int d, const vector<int>& b) {
    vector<int> ans;
    ans.push_back(b[0]);

    // 依次处理每个要保留的元素
    for (int i = 1; i < n; i++) {
        // 如果当前元素直接接在前一个保留元素后面仍能被保留
        if ((long long)b[i - 1] + d <= b[i]) {
            ans.push_back(b[i]);
        } else {
            // 否则必须插入一个数
            // 只插入一个即可保证长度最短
            // 插入 1 可以保证字典序最小
            ans.push_back(1);
            ans.push_back(b[i]);
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, d;
        cin >> n >> d;

        vector<int> b(n);
        for (int i = 0; i < n; i++) {
            cin >> b[i];
        }

        vector<int> ans = buildSequence(n, d, b);

        cout << ans.size() << '\n';
        for (int i = 0; i < (int)ans.size(); i++) {
            if (i > 0) {
                cout << ' ';
            }
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}
